SELECT d.*,vm.machine_name
FROM t_specify_machine_list d,V_MACHINE_INFO vm

    d.procedure_code = vm.procedure_code
    AND d.machine_id = to_char(vm.machine_id)
    AND d.del_flag = '0'
    and d.specify_machine_id = #{specifyMachineId}
    and d.procedure_code = #{procedureCode}
    and d.machine_id = #{machineId}


    order by create_time desc


    order by ${orderStr}

SELECT PROCEDURE_CODE,MACHINE_ID, MACHINE_CODE, MACHINE_NAME
FROM V_MACHINE_INFO vm

    and procedure_code = #{procedureCode}
    and machine_id = #{machineId}

